send-request.set-body:
@{
    var callers = new JArray();
    if (context.Subscription != null) { callers.Add(new JObject(new JProperty("kind", "subscription"), new JProperty("id", context.Subscription.Id))); }
    if (context.User != null && !string.IsNullOrEmpty(context.User.Id)) { callers.Add(new JObject(new JProperty("kind", "user"), new JProperty("id", context.User.Id))); }
    if (context.Product != null) { callers.Add(new JObject(new JProperty("kind", "product"), new JProperty("id", context.Product.Id))); }
    var req = new JObject(
        new JProperty("gateway", new JObject(new JProperty("kind", "azure_apim"))),
        new JProperty("callers", callers),
        new JProperty("provider", "azure.ai.openai"),
        new JProperty("model", ((string)context.Variables["tcModel"])),
        new JProperty("correlation_id", context.RequestId.ToString()));
    var maxTokens = ((string)context.Variables["tcMaxTokens"]);
    if (maxTokens != "") { req["max_tokens"] = maxTokens; }
    var stream = ((JObject)context.Variables["tcBody"])["stream"] as JValue;
    if (stream != null) { req["stream"] = stream; }
    if (((bool)context.Variables["tcModelInPath"])) { req["can_reroute"] = false; }
    var customer = ((string)context.Variables["tcCustomer"]);
    if (customer != "") { req["customer"] = customer; }
    return req.ToString(Newtonsoft.Json.Formatting.None);
}

return-response.set-body:
@{
    var a = (JObject)context.Variables["tcAnswer"];
    var e = new JObject(new JProperty("type", "budget_check_unavailable"), new JProperty("message", "TensorCost couldn't check this call's budget, and this gateway refuses calls it can't check."));
    return new JObject(new JProperty("error", e)).ToString(Newtonsoft.Json.Formatting.None);
}

@{
    var a = (JObject)context.Variables["tcAnswer"];
    var e = new JObject(new JProperty("type", "budget_check_unavailable"), new JProperty("message", (string)(((JObject)context.Variables["tcAnswer"])["message"] as JValue) ?? "TensorCost couldn't check this call's budget, and this gateway refuses calls it can't check."));
    e["reason"] = (string)(((JObject)context.Variables["tcAnswer"])["reason"] as JValue);
    e["retry_after_seconds"] = a["retry_after_seconds"];
    return new JObject(new JProperty("error", e)).ToString(Newtonsoft.Json.Formatting.None);
}

