    var e = new JObject(new JProperty("type", "budget_check_unavailable"), new JProperty("message", (string)(((JObject)context.Variables["tcAnswer"])["message"] as JValue) ?? "TensorCost couldn't check this call's budget, and this gateway refuses calls it can't check."));
    e["reason"] = (string)(((JObject)context.Variables["tcAnswer"])["reason"] as JValue);
    return new JObject(new JProperty("error", e)).ToString(Newtonsoft.Json.Formatting.None);
